const _CART_MAX_QTY=4;function gCart(){try{return JSON.parse(localStorage.getItem('cart')||'{}')}catch(e){return{}}}function sCart(c){localStorage.setItem('cart',JSON.stringify(c))}function cartCount(c){return Object.values(c).reduce((n,it)=>n+it.quant,0)}function cartTotal(c){return Object.values(c).reduce((t,it)=>t+it.price*it.quant,0)}function updateBadge(){const el=document.getElementById('cart-count');if(!el)return;const n=cartCount(gCart());el.textContent=n>0?n:'';el.hidden=n===0}function setQuant(id,quant){const c=gCart();if(quant<=0){delete c[id]}else if(c[id]){c[id].quant=Math.min(quant,_CART_MAX_QTY)}sCart(c);updateBadge();renderCart()}function addToCart(id,name,price){const c=gCart();if(c[id]){c[id].quant=Math.min(c[id].quant+1,_CART_MAX_QTY)}else{c[id]={id:Number(id),name:name,price:Number(price),quant:1}}sCart(c);updateBadge()}function refNumInput(){return document.getElementById('ref-num-input')}function refNumValid(){const el=refNumInput();return!!el&&/^[0-9]{25}$/.test(el.value)}function updateContinueState(){const btn=document.getElementById('cart-continue');if(!btn)return;btn.disabled=cartCount(gCart())===0||!refNumValid()}function renderCart(){const list=document.getElementById('cart-list');if(!list)return;const c=gCart();const ids=Object.keys(c);list.innerHTML='';if(ids.length===0){list.innerHTML='<p class="empty-msg">El carrito está vacío</p>'}else{ids.forEach(id=>{const it=c[id];const row=document.createElement('div');row.className='cart-row';row.innerHTML='<span class="cart-row-name">'+it.name+'</span>'+'<span class="cart-row-price">₡'+it.price+'</span>'+'<span class="cart-row-qty">'+'<button type="button" class="btn btn-compact" data-qty-step="-1" data-id="'+id+'">−</button>'+'<span class="cart-row-qty-num">'+it.quant+'</span>'+'<button type="button" class="btn btn-compact" data-qty-step="1" data-id="'+id+'"'+(it.quant>=_CART_MAX_QTY?' disabled':'')+'>+</button>'+'</span>'+'<span class="cart-row-subtotal">₡'+(it.price*it.quant)+'</span>'+'<button type="button" class="btn btn-compact" data-qty-remove data-id="'+id+'">Quitar</button>';list.appendChild(row)})}const totalEl=document.getElementById('cart-total');if(totalEl){totalEl.textContent='₡'+cartTotal(c)}updateContinueState()}function extractRefNum(text){const runs=text.match(/[0-9 ]{20,}/g)||[];for(const run of runs){const d=run.replace(/\s/g,'');if(d.length===25)return d}const all=text.replace(/\D/g,'');return all.length===25?all:''}function scanRefImg(file){const status=document.getElementById('ref-status');const confirm=document.getElementById('ref-confirm');const input=refNumInput();if(!status||!confirm||!input)return;status.hidden=false;status.textContent='Escaneando comprobante...';confirm.hidden=true;updateContinueState();Tesseract.recognize(file,'eng').then(({data:{text}})=>{const code=extractRefNum(text);input.value=code;confirm.hidden=false;status.textContent=code?'Código detectado. Verifique antes de enviar.':'No se detectó código. Ingréselo manualmente.';updateContinueState()}).catch(()=>{confirm.hidden=false;status.textContent='No se pudo leer la imagen. Ingrese el código manualmente.';updateContinueState()})}function submitOrder(){if(!refNumValid())return;const c=gCart();if(cartCount(c)===0)return;const items={};Object.values(c).forEach(it=>{items[it.id]=it.quant});const btn=document.getElementById('cart-continue');const result=document.getElementById('order-result');btn.disabled=true;fetch('/order',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':(typeof gC==='function'?gC('csrf-token'):''),'HX-Request':'true'},body:JSON.stringify({ref_num:refNumInput().value,items:items})}).then(res=>res.text().then(body=>({ok:res.ok,body:body}))).then(({ok,body})=>{if(result)result.innerHTML=body;if(ok){localStorage.removeItem('cart');updateBadge();renderCart()}else{updateContinueState()}}).catch(()=>{if(result)result.innerHTML='<div class="hx-flash"><p class="hx-msg">No se pudo enviar la orden.</p></div>';updateContinueState()})}document.body.addEventListener('click',function(e){const add=e.target.closest('[data-cart-add]');if(add){addToCart(add.dataset.itemId,add.dataset.itemName,add.dataset.itemPrice);const old=add.textContent;add.textContent='Agregado ✓';add.disabled=true;setTimeout(()=>{add.textContent=old;add.disabled=false},900);return}const step=e.target.closest('[data-qty-step]');if(step){const c=gCart();const id=step.dataset.id;const d=Number(step.dataset.qtyStep);setQuant(id,(c[id]?c[id].quant:0)+d);return}const rm=e.target.closest('[data-qty-remove]');if(rm){setQuant(rm.dataset.id,0);return}const cont=e.target.closest('#cart-continue');if(cont&&!cont.disabled){submitOrder();return}});document.body.addEventListener('change',function(e){if(e.target.id==='ref-img-input'){const f=e.target.files&&e.target.files[0];if(f)scanRefImg(f)}});document.body.addEventListener('input',function(e){if(e.target.id==='ref-num-input')updateContinueState()});document.body.addEventListener('htmx:load',function(){updateBadge();renderCart()});
